CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0', "invite_token" varchar, "invite_token_expires_at" datetime, "two_factor_code" varchar, "two_factor_expires_at" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "two_factor_last_used_step" integer);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "machines" ("id" integer primary key autoincrement not null, "name" varchar not null, "host" varchar not null, "port" integer not null default '8765', "os" varchar check ("os" in ('windows', 'linux', 'macos', 'other')) not null default 'other', "agent_token" text not null, "color" varchar not null default '#8c7a63', "icon" varchar not null default 'desktop', "sort_order" integer not null default '0', "use_tls" tinyint(1) not null default '0', "status" varchar not null default 'unknown', "last_seen_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, "low_space_alerted_at" datetime);
CREATE TABLE "machine_user" ("id" integer primary key autoincrement not null, "machine_id" integer not null, "user_id" integer not null, "role" varchar check ("role" in ('read_only', 'full')) not null default 'read_only', "created_at" datetime, "updated_at" datetime, foreign key("machine_id") references "machines"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "disk_readings" ("id" integer primary key autoincrement not null, "machine_id" integer not null, "free_bytes" integer not null, "total_bytes" integer not null, "recorded_at" datetime not null, foreign key("machine_id") references "machines"("id") on delete cascade);
CREATE TABLE "relay_transfers" ("id" integer primary key autoincrement not null, "source_machine_id" integer not null, "destination_machine_id" integer not null, "source_path" varchar not null, "destination_path" varchar not null, "kind" varchar check ("kind" in ('copy', 'move')) not null default 'copy', "status" varchar check ("status" in ('queued', 'downloading', 'uploading', 'done', 'error')) not null default 'queued', "error" text, "user_id" integer, "created_at" datetime, "updated_at" datetime, "bytes_transferred" integer, "started_at" datetime, "completed_at" datetime, "is_directory" tinyint(1) not null default '0', foreign key("source_machine_id") references "machines"("id") on delete cascade, foreign key("destination_machine_id") references "machines"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "sync_rules" ("id" integer primary key autoincrement not null, "name" varchar not null, "source_machine_id" integer not null, "source_path" varchar not null, "destination_machine_id" integer not null, "destination_path" varchar not null, "direction" varchar check ("direction" in ('one_way', 'mirror')) not null default 'one_way', "interval_minutes" integer not null default '60', "enabled" tinyint(1) not null default '1', "last_run_at" datetime, "has_conflict" tinyint(1) not null default '0', "last_error" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("source_machine_id") references "machines"("id") on delete cascade, foreign key("destination_machine_id") references "machines"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "machine_user_machine_id_user_id_unique" on "machine_user" ("machine_id", "user_id");
CREATE INDEX "disk_readings_machine_id_recorded_at_index" on "disk_readings" ("machine_id", "recorded_at");
CREATE UNIQUE INDEX "users_invite_token_unique" on "users" ("invite_token");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
